mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY M.CREATED_AT DESC) AS RN, M.MEMBER_ID, M.UNIV_ID, U.UNIV_NAME, U.SCHOOL_PHONE, U.ADDRESS, MD.DEPT_ID, M.MEMBER_NAME, M.ROLE, M.PHONE_NUMBER, M.GENDER, M.STATUS, M.CREATED_AT, MD.COMMUNITY_NICKNAME FROM MEMBER M LEFT JOIN MEMBER_DETAIL MD ON M.MEMBER_ID = MD.MEMBER_ID LEFT JOIN UNIVERSITY U ON M.UNIV_ID = U.UNIV_ID WHERE 1=1
AND M.MEMBER_ID = #{memberId}
AND M.MEMBER_NAME LIKE '%' || #{memberName} || '%'
AND MD.DEPT_ID = #{deptId}
AND M.UNIV_ID = #{univId}
) WHERE RN BETWEEN (#{page} - 1) * #{size} + 1 AND #{page} * #{size}

SELECT COUNT(*)
FROM MEMBER M
LEFT JOIN MEMBER_DETAIL MD ON M.MEMBER_ID = MD.MEMBER_ID
WHERE 1=1

    AND M.MEMBER_ID = #{memberId}


    AND M.MEMBER_NAME LIKE '%' || #{memberName} || '%'


    AND MD.DEPT_ID = #{deptId}


    AND M.UNIV_ID = #{univId}

mapper.update:
UPDATE MEMBER
SET STATUS = #{status}
WHERE MEMBER_ID = #{memberId}

UPDATE NOTICE
SET IS_DELETED = 1
WHERE NOTICE_ID = #{noticeId}

mapper.select:
SELECT S.SUPPORT_ID, S.MEMBER_ID, S.UNIV_ID, U.UNIV_NAME, S.MEMBER_NAME, S.CONTACT, S.MESSAGE, S.STATUS, S.CREATED_AT FROM SUPPORT S JOIN UNIVERSITY U ON S.UNIV_ID = U.UNIV_ID
S.UNIV_ID = #{univId}
ORDER BY S.CREATED_AT DESC

mapper.update:
UPDATE SUPPORT
SET STATUS = #{status}
WHERE SUPPORT_ID = #{supportId}

mapper.select:
SELECT UNIV_ID, UNIV_NAME, SCHOOL_PHONE, HOMEPAGE, ADDRESS, YOUTUBE_URL, CLUB_URL, SNS_URL
FROM UNIVERSITY
WHERE UNIV_ID = #{univId}

mapper.update:
UPDATE UNIVERSITY
SET YOUTUBE_URL = #{dto.youtubeUrl},
    CLUB_URL    = #{dto.clubUrl},
    SNS_URL     = #{dto.snsUrl}
WHERE UNIV_ID = #{univId}

mapper.select:
SELECT LC.LEC_CODE_ID, LC.DEPT_ID, D.DEPT_NAME, D.UNIV_ID, U.UNIV_NAME, LC.LEC_CODE, LC.LEC_COD_NAME, LC.VAL_STATUS FROM LECTURE_CODE LC JOIN DEPARTMENT D ON LC.DEPT_ID = D.DEPT_ID JOIN UNIVERSITY U ON D.UNIV_ID = U.UNIV_ID
D.UNIV_ID = #{univId}
ORDER BY LC.LEC_CODE_ID

mapper.update:
UPDATE LECTURE_CODE
SET LEC_CODE     = #{lecCode},
    LEC_COD_NAME = #{lecCodName}
WHERE LEC_CODE_ID = #{lecCodeId}

UPDATE LECTURE_CODE
SET VAL_STATUS = #{valStatus}
WHERE LEC_CODE_ID = #{lecCodeId}

mapper.select:
SELECT WEATHER, AI_CHAT, NOTICE, MEAL, TEL, SHORTCUT
FROM UNIV_HOME_CONFIG
WHERE UNIV_ID = #{univId}

mapper.update:
UPDATE UNIV_HOME_CONFIG
WEATHER = #{dto.weather}, AI_CHAT = #{dto.aiChat}, NOTICE = #{dto.notice}, MEAL = #{dto.meal}, TEL = #{dto.tel}, SHORTCUT = #{dto.shortcut},
WHERE UNIV_ID = #{univId}

mapper.select:
SELECT DEFAULT_TARGET, SHOW_TOP, PUSH_ALERT
FROM UNIV_NOTICE_CONFIG
