mapper.update:
UPDATE UNIV_NOTICE_CONFIG
DEFAULT_TARGET = #{dto.defaultTarget}, SHOW_TOP = #{dto.showTop}, PUSH_ALERT = #{dto.pushAlert},
WHERE UNIV_ID = #{univId}

mapper.select:
SELECT L.LEC_ID, LC.LEC_CODE_ID, LC.LEC_CODE, LC.LEC_COD_NAME, D.DEPT_ID, D.DEPT_NAME, D.UNIV_ID, U.UNIV_NAME, M.MEMBER_ID AS PROFESSOR_MEMBER_ID, M.MEMBER_NAME AS PROFESSOR_NAME, S.SEM_ID, S.SEM_YEAR, S.SEM_TERM, L.LEC_SECTION, L.LEC_CREDIT, L.LEC_TOT_CLASSES, L.LEC_VAL_STATUS, (SELECT LISTAGG(LT.LEC_TIM_DAY_CODE, ',') WITHIN GROUP (ORDER BY LT.LEC_TIM_ID) FROM LECTURE_TIME LT WHERE LT.LEC_ID = L.LEC_ID) AS DAY_CODES, (SELECT TO_CHAR(MIN(LT.LEC_TIM_STR_TIME), 'HH24:MI') FROM LECTURE_TIME LT WHERE LT.LEC_ID = L.LEC_ID) AS START_TIME, (SELECT TO_CHAR(MAX(LT.LEC_TIM_END_TIME), 'HH24:MI') FROM LECTURE_TIME LT WHERE LT.LEC_ID = L.LEC_ID) AS END_TIME FROM LECTURE L JOIN LECTURE_CODE LC ON LC.LEC_CODE_ID = L.LEC_CODE_ID JOIN DEPARTMENT D ON D.DEPT_ID = LC.DEPT_ID JOIN UNIVERSITY U ON U.UNIV_ID = D.UNIV_ID JOIN SEMESTERS S ON S.SEM_ID = L.SEM_ID JOIN LMS_PROFILE LP ON LP.LMS_PRF_ID = L.LMS_PRF_ID JOIN MEMBER M ON M.MEMBER_ID = LP.MEMBER_ID
D.UNIV_ID = #{univId}
AND L.SEM_ID = #{semId}
ORDER BY S.SEM_ID DESC, LC.LEC_COD_NAME, L.LEC_SECTION, L.LEC_ID

SELECT NVL(MAX(LEC_SECTION), 0) + 1
FROM LECTURE
WHERE SEM_ID = #{semId}
  AND LEC_CODE_ID = #{lecCodeId}

SELECT COUNT(*)
FROM LECTURE L
JOIN LECTURE_TIME LT ON LT.LEC_ID = L.LEC_ID
WHERE L.SEM_ID = #{semId}
  AND L.LMS_PRF_ID = #{lmsPrfId}
  AND L.LEC_VAL_STATUS != 'CNCL'
  AND LT.LEC_TIM_DAY_CODE = #{dayCode}
  AND TO_CHAR(LT.LEC_TIM_STR_TIME, 'HH24:MI') < #{endTime}
  AND TO_CHAR(LT.LEC_TIM_END_TIME, 'HH24:MI') > #{startTime}

    AND L.LEC_ID != #{excludeLecId}

SELECT MIN(LMS_PRF_ID)
FROM LMS_PROFILE
WHERE MEMBER_ID = #{memberId}

SELECT M.MEMBER_ID, M.MEMBER_NAME, D.DEPT_NAME FROM MEMBER M LEFT JOIN MEMBER_DETAIL MD ON M.MEMBER_ID = MD.MEMBER_ID LEFT JOIN DEPARTMENT D ON MD.DEPT_ID = D.DEPT_ID WHERE M.ROLE = 'PROF'
AND M.UNIV_ID = #{univId}
ORDER BY M.MEMBER_NAME, M.MEMBER_ID

SELECT LC.LEC_CODE_ID, LC.DEPT_ID, D.DEPT_NAME, D.UNIV_ID, U.UNIV_NAME, LC.LEC_CODE, LC.LEC_COD_NAME, LC.VAL_STATUS, (SELECT COUNT(*) FROM LECTURE L WHERE L.LEC_CODE_ID = LC.LEC_CODE_ID) AS ASSIGN_COUNT FROM LECTURE_CODE LC JOIN DEPARTMENT D ON LC.DEPT_ID = D.DEPT_ID JOIN UNIVERSITY U ON D.UNIV_ID = U.UNIV_ID
D.UNIV_ID = #{univId}
ORDER BY LC.LEC_CODE_ID

SELECT COUNT(*)
FROM LECTURE_CODE
WHERE DEPT_ID = #{deptId}
  AND LEC_CODE = #{lecCode}

    AND LEC_CODE_ID != #{excludeLecCodeId}

SELECT COUNT(*)
FROM LECTURE
WHERE LEC_CODE_ID = #{lecCodeId}

mapper.update:
UPDATE LECTURE_CODE
SET VAL_STATUS = 'DEL'
WHERE LEC_CODE_ID = #{lecCodeId}
